-- Save MJ: Query SQLs (core SP call only)
DECLARE @SQL_9d5b364ac7de NVARCHAR(MAX),
@ID_9d5b364ac7de UNIQUEIDENTIFIER
SET
  @SQL_9d5b364ac7de = N'-- PostgreSQL variant: Get Artifact Versions By ID
-- Mirrors get-artifact-versions-by-id.sql for PG. Differences:
--   * `[${flyway:defaultSchema}].[X]` → `${flyway:defaultSchema}."X"` (schema brackets removed, view names quoted).
--   * Bare PascalCase column refs double-quoted to survive PG''s case-folding.

SELECT
    av."ID" AS "VersionID",
    av."ArtifactID" AS "ArtifactID",
    av."VersionNumber" AS "VersionNumber",
    av."Name" AS "VersionName",
    av."Description" AS "VersionDescription",
    av."ContentMode",
    av."FileID",
    av."Content",
    av."MimeType",
    av."ForceToolsOnly",

    a."Name" AS "ArtifactName",
    a."Description" AS "ArtifactDescription",
    a."Type" AS "TypeName",

    at."ToolLibraryClass",
    at."DefaultDeliveryMode"

FROM ${flyway:defaultSchema}."vwArtifactVersions" av
INNER JOIN ${flyway:defaultSchema}."vwArtifacts" a ON av."ArtifactID" = a."ID"
INNER JOIN ${flyway:defaultSchema}."vwArtifactTypes" at ON a."TypeID" = at."ID"

WHERE av."ID" IN {{ versionIds | sqlIn }}
ORDER BY av."__mj_CreatedAt" ASC, av."VersionNumber" ASC
'
SET
  @ID_9d5b364ac7de = '3659BD9A-71AF-448E-8567-6E531BA58BBA' EXEC [${flyway:defaultSchema}].spUpdateQuerySQL @SQL = @SQL_9d5b364ac7de,
  @ID = @ID_9d5b364ac7de;

GO

-- Save MJ: Queries (core SP call only)
DECLARE @SQL_41a1ddae6527 NVARCHAR(MAX),
@ID_41a1ddae6527 UNIQUEIDENTIFIER
SET
  @SQL_41a1ddae6527 = N'-- Get Conversation Complete - Single optimized query for conversation loading
-- Returns ALL data needed to display a conversation: messages, agent runs, and artifacts
-- Uses JSON aggregation to include related data without row multiplication
-- This replaces 4 separate queries with 1 query for ~70% performance improvement
SELECT
    -- Conversation Detail fields (all fields needed for display)
    cd.*,

    -- User Avatar fields from vwUsers (for message display)
    -- These fields come from the LEFT JOIN to User table in vwConversationDetails
    u.UserImageURL,
    u.UserImageIconClass,

    -- Agent Runs as JSON array (0-1 per conversation detail)
    -- Only includes fields needed for display in the gear icon
    (
        SELECT
            ar.ID, 
            ar.AgentID,
            ar.Agent,
            ar.ParentRunID,
            ar.ContinuationDepth,
            ar.Status,
            ar.__mj_CreatedAt,
            ar.__mj_UpdatedAt,
            ar.TotalPromptTokensUsed,
            ar.TotalCompletionTokensUsed,
            ar.TotalCost,
            ar.ConversationDetailID
        FROM [${flyway:defaultSchema}].[vwAIAgentRuns] ar
        WHERE ar.ConversationDetailID = cd.ID
        ORDER BY
            CASE WHEN ar.ParentRunID IS NULL THEN 0 ELSE 1 END ASC,
            ISNULL(ar.ContinuationDepth, 0) ASC,
            ar.__mj_CreatedAt DESC
        FOR JSON PATH
    ) as AgentRunsJSON,

    -- Artifacts as JSON array (0-N per conversation detail)
    -- Only includes fields needed for display in artifact cards
    -- Excludes heavy Content field for performance
    (
        SELECT
            cda.ConversationDetailID,
            cda.Direction,
            av.ID as ArtifactVersionID,
            av.VersionNumber,
            av.Name as VersionName,
            av.Description as VersionDescription,
            av.__mj_CreatedAt as VersionCreatedAt,
            av.ArtifactID,
            a.Name as ArtifactName,
            a.Type as ArtifactType,
            a.Description as ArtifactDescription,
            a.Visibility as Visibility
        FROM [${flyway:defaultSchema}].[vwConversationDetailArtifacts] cda
        INNER JOIN [${flyway:defaultSchema}].[vwArtifactVersions] av ON cda.ArtifactVersionID = av.ID
        INNER JOIN [${flyway:defaultSchema}].[vwArtifacts] a ON av.ArtifactID = a.ID
        WHERE cda.ConversationDetailID = cd.ID
          AND cda.Direction = ''Output''
        ORDER BY cda.__mj_CreatedAt, av.VersionNumber
        FOR JSON PATH
    ) as ArtifactsJSON,

    -- Ratings as JSON array (0-N per conversation detail)
    -- Includes all user ratings for multi-user support
    (
        SELECT
            cdr.ID,
            cdr.UserID,
            cdr.Rating,
            cdr.Comments,
            cdr.__mj_CreatedAt,
            u.Name as UserName
        FROM [${flyway:defaultSchema}].[vwConversationDetailRatings] cdr
        INNER JOIN [${flyway:defaultSchema}].[vwUsers] u ON cdr.UserID = u.ID
        WHERE cdr.ConversationDetailID = cd.ID
        ORDER BY cdr.__mj_CreatedAt DESC
        FOR JSON PATH
    ) as RatingsJSON

FROM [${flyway:defaultSchema}].[vwConversationDetails] cd
LEFT OUTER JOIN [${flyway:defaultSchema}].[vwUsers] u ON cd.UserID = u.ID
WHERE cd.ConversationID = {{ ConversationID | sqlString }}
ORDER BY cd.__mj_CreatedAt ASC
'
SET
  @ID_41a1ddae6527 = '8F84DFB4-C38E-4B8D-80E7-9CCF30039E77' EXEC [${flyway:defaultSchema}].spUpdateQuery @SQL = @SQL_41a1ddae6527,
  @ID = @ID_41a1ddae6527;

GO

